"""Generate docs/brains/depth/DEPTH_STAGE_AREA_RATING_RULES.md from the committed manifest, curves and contour-truth snapshot (no network)."""
import csv, json, os, sys
from collections import Counter
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.join(HERE, "..", "..")
sys.path.insert(0, os.path.join(ROOT, "jobs", "depth-brain"))
from depth_brain import rating as R  # noqa: E402

D = os.path.join(ROOT, "jobs/depth-brain/depth_brain/data")
M = {c["lakeId"]: c for c in json.load(open(f"{D}/candidates.json"))["candidates"]}
CUR = json.load(open(f"{D}/stage_area_curves.json"))
cur, rej = CUR["lakes"], CUR["rejected"]
rated = {k: v for k, v in M.items() if (v.get("referenceZones") or {}).get("kind") == "stage-area-rating"}
withheld = {k: v["ratingZoneWithheld"] for k, v in M.items() if v.get("ratingZoneWithheld")}
sp = [k for k, v in rated.items() if v["shiftPossible"]]

# cross-check against independent contour surveys (interval <= 5 ft)
rows = list(csv.DictReader(open(f"{D}/inputs/contour_truth_lakes.csv")))
diffs, per = [], []
for r in rows:
    lid = r["lakeId"]
    if lid not in cur or not r.get("interval_ft") or float(r["interval_ft"]) > 5:
        continue
    try:
        ct = {3.0: float(r["shr_0_3"]), 6.0: float(r["shr_0_3"]) + float(r["shr_3_6"]), 10.0: float(r["shr_0_3"]) + float(r["shr_3_6"]) + float(r["shr_6_10"])}
    except (TypeError, ValueError):
        continue
    cum = R.cumulative_at(cur[lid], cur[lid]["poolFt"])
    dd = [abs(cum[k] - ct[k]) for k in cum]
    diffs += dd; per.append((lid, r["interval_ft"], round(max(dd), 3)))
a = sorted(diffs); q = lambda p: a[min(len(a) - 1, int(p * len(a)))]
vint = Counter("unknown (CWMS default 1970-01-01)" if v["effectiveDate"].startswith("1970") else ("before 1990" if v["effectiveDate"] < "1990" else "1990 or later") for v in (cur[k] for k in rated))
tier = Counter(rated[k]["evidence"]["tier"] for k in rated)
by_reason = {}
for k, v in withheld.items():
    by_reason.setdefault(v, []).append(k)

L = [f"""# Depth Brain: Operator Elevation-Area Ratings as Depth-Share Evidence (RATING-ZONE-RULES-1)

Generated by `research/depth/stage_area_doc.py` from `depth_brain/data/{{candidates,stage_area_curves}}.json`. Builders: `research/depth/stage_area_build.py` (USACE CWMS Data API ratings and Reclamation TSC tables, read-only GETs, fetched 2026-10-14), `tsc_tables_parse.py` / `tsc_equations_parse.py` (TSC PDFs), `rise_storage_link.py` and `reclamation_pool_frame.py` (the datum chain for Reclamation lakes). Code: `depth_brain/rating.py`, `zones.py`, `state.py`, `candidates.py`. Tests: `tests/test_rating_zones.py`.

## 1. What this adds, and what it does not

A USACE CWMS `Elev;Area` rating states the water-surface area at every elevation. With the reference pool P, the share of the pool surface whose bottom lies within x ft below P is `S(x) = (A(P) - A(P-x)) / A(P)`. That is exactly the cumulative depth-share function a contour survey approximates, so for a lake with such a rating Depth can answer: **how much of the lake is dry now, and how much is under 3 ft / 3-6 ft / 6-10 ft / deeper** at the current level (the same bands as the contour product).

It says **how much, never where.** No polygon, flat, drop-off, channel or point depth comes from it. This is the "measured hypsometry" row of the evidence policy (tier C: only the statements the evidence itself supports), now implemented for operator ratings. GLOBathy/DEM hypsometry stay forbidden: those are modelled; a rating is the operator's own published elevation-area function.

## 2. Rules (defined in code before the results were inspected; amendments listed in section 3)

| Rule | Text |
|---|---|
| R1 source | USACE CWMS `Elev;Area` rating, units ft;acre, latest effective date (preferring a version in the pool's datum), or a Reclamation TSC survey area table (ACAP equations or the printed 1-ft area table) for lakes whose Reclamation datum chain passed (section 4b). `Stage;Area` ratings (gauge-zero assumption) are not used. |
| R2 frame | The rating must be in the pool's elevation frame: (a) rating at the CWMS location of the level SERIES and the series/pool relationship is SAME_SOURCE or SAME_DATUM, or (b) rating at the location of a verified, NAMED pool datum; and a named rating datum must equal the pool datum. |
| R3 range | The rating's pool must be the Depth reference pool, P lies inside the rating, and P-3 ft is rated. An edge whose P-x is below the lowest rated elevation is not published as a point; its share is bounded `[S(floor), 1]` and a wide band is withheld (25-point rule). Never extrapolated. |
| R4 monotone | Area must not fall with elevation by more than 1% of the largest stored area (below pool + 6 ft). |
| R5 vintage | The rating's CWMS effective date is shown, never described as a survey year; `1970-01-01` is CWMS' default and is shown as vintage unknown. |
| R6 cross-check | If the lake also has a contour survey with shares, the rating is used only if every common edge agrees within 0.10 of the surface; otherwise zones are withheld (`R6_RATING_CONTOUR_DISAGREE`). A validated contour reference (TWDB) keeps priority. |
| R7 claims | Shares of the reference-pool surface (dry, under 3, 3-6, 6-10, deeper) with bounds from the shift uncertainty, plus the reported tolerance below. Evidence tier C (A/B contour lakes keep their tier), kind `stage-area-rating`, licence `USACE_CWMS`. |
| R8 tolerance | Every rating-derived share carries `shareToleranceAbs = {R.RATING_SHARE_TOLERANCE_ABS}`: the 90th-percentile disagreement with independent contour surveys (section 5). It is a reported accuracy, not a bound. |

## 3. Amendments made after seeing results (disclosed)

1. The first pass picked the latest rating regardless of datum; 10 Kansas/Iowa/Missouri lakes were refused as `R2_RATING_DATUM_DIFFERS` (11 after amendment 4 admitted Smithville to the rating list). The selector now prefers a rating in the pool's datum; it changed nothing for those lakes: their only rating is NGVD29 while the A2W series/pool is LOCAL. Eight of them were later admitted through the LOCAL == NGVD29 equivalence evidence (amendment 6).
2. R6 was added after three lakes (Senecaville, Tygart, Canyon Ferry) showed large contour/rating differences. It only withholds; it never publishes. (Canyon Ferry then passed at the 0.10 gate; Tygart was later refused by R4 instead; Senecaville is withheld by R6.)
3. A `ft;ft2` rating (Alamo) was tried with a unit conversion and dropped: the converted area at pool was about 0.1 acre, so the unit label is unreliable.
4. The monotone check was moved to the stored region (below pool + 6 ft) so noise above the pool cannot reject a lake (Truman and Allegheny then qualified and Smithville reached R2; Tygart, Youghiogheny and Table Rock are still refused).
6. R2 gained the LOCAL == NGVD29 equivalence clause (section 4) after the refusals were read; it needs a per-lake paired-series proof and never applies generally.
5. Ratings with more than 400 points at under 0.1 ft spacing are resampled to a 0.1 ft grid (linear between points) to keep the committed file at about 260 KB.

## 4. Result

* Source mix of accepted curves: {dict(Counter(v['matchedBy'] for v in cur.values()))}.
* Ratings fetched and accepted by the builder: **{len(cur)}**; refused by the builder: {len(rej)} ({', '.join(f'{k}: {v}' for k, v in rej.items())}).
* Lakes whose manifest now carries rating-derived reference shares (R1-R6 passed): **{len(rated)}**, of which **{len(sp)}** have a defensible shift today (zones become effective-zone output as soon as Lake Brain publishes a level).
* Evidence tier of those lakes: {dict(tier)}. Rating vintage: {dict(vint)}.
* Withheld after the builder, with the rule that withheld them: {'; '.join(f"{r} ({len(v)}): {', '.join(sorted(v))}" for r, v in sorted(by_reason.items()))}.
  * `R2_RATING_DATUM_DIFFERS` lakes have an NGVD29 rating but a LOCAL A2W series/pool. Where a paired USGS series proves LOCAL equals NGVD29 numerically (`local_datum_equivalence.json`, from `research/depth/local_equivalence.py`: n >= 20, |mean| <= 0.10 ft, SD <= 0.25 ft, not circular) R2 accepts it: Clinton, Kanopolis, Melvern, Milford, Perry, Pomona, Tuttle Creek and Wilson. The remaining ones (no USGS lake-elevation series near the dam) wait for an operator statement or a gauge.

## 5. Independent cross-check (the evidence behind R6 and R8)

Rating shares vs contour-survey shares at the 3, 6 and 10 ft edges, lakes whose contour interval is 5 ft or finer: **{len(per)} lakes, {len(a)} edges, median |difference| {q(.5):.3f}, 75th percentile {q(.75):.3f}, 90th percentile {q(.9):.3f}, maximum {a[-1]:.3f}.** The two sources are independent (a survey of the water body vs the operator's published rating) and each has its own error, so these differences are an upper bound on the rating's error only if the contours were exact, which they are not. Largest per-lake maxima: {', '.join(f'{l} ({d})' for l, i, d in sorted(per, key=lambda x: -x[2])[:6])}.

## 6. What remains unvalidated

* The physical lake. A rating can be old or pre-impoundment: {vint.get('before 1990', 0)} of the {len(rated)} accepted ratings have an effective date before 1990 and {vint.get('unknown (CWMS default 1970-01-01)', 0)} have an unknown one. Vintage is published beside every share.
* Level-3 interpretation (does "12% under 3 ft" match what a bowfisher sees): field validation, same as every other Depth claim.
* Licence: the USACE terms page returned HTTP 403 to automated fetch; `USACE_CWMS` is recorded as an assumed federal-work classification and is in the Michael decision list.

## 7. Lakes

| Lake | Rating | Effective | Tier | Shift now | Pool ft | Under 3 / 6 / 10 ft share at pool |
|---|---|---|---|---|---|---|
"""]
for k in sorted(rated):
    z = rated[k]["referenceZones"]; c = z["cumulative"]
    L.append(f"| {k.replace(chr(124), ' / ')} | {z['rating']['id']} | {z['rating']['effectiveDate']}{'' if z['rating']['vintageKnown'] else ' (default)'} | {rated[k]['evidence']['tier']} | {'yes' if rated[k]['shiftPossible'] else 'no'} | {z['referencePoolFt']} | {c.get('3.0', '-')} / {c.get('6.0', '-')} / {c.get('10.0', '-')} |\n")
open(os.path.join(ROOT, "docs/brains/depth/DEPTH_STAGE_AREA_RATING_RULES.md"), "w").write("".join(L))
print(len(rated), len(sp), dict(tier), dict(vint), {r: len(v) for r, v in by_reason.items()})
